function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// half-open [start,end); null for t>=60 or no active cue
export function captionAt(t) {
  t = Number(t);
  if (!(t >= 0) || t >= 60.0) return null;
  for (let i = 0; i < CUES.length; i++) {
    const c = CUES[i];
    if (t >= c.start && t < c.end) return c;
  }
  return null;
}

